const input = $input.first().json;

// Se já veio processado (caminho do áudio)
if (input.phone && input.message) {
  return [{ json: input }];
}

// Caminho texto: processa o webhook bruto
const body = (input.body) || {};
const data = body.data || {};
const key = data.key || {};
const remoteJid = key.remoteJid || '';
const fromMe = key.fromMe || false;

if (fromMe) return [];

const phone = remoteJid.split('@')[0].replace(/[^0-9]/g, '');
if (!phone) return [];

const msgData = data.message || {};
const message = input.merged_message
  || msgData.conversation
  || (msgData.extendedTextMessage && msgData.extendedTextMessage.text)
  || '';

if (!message.trim()) {
  console.log('[TradeBrasil] Descartando mensagem vazia para phone=' + phone);
  return [];
}

return [{
  json: {
    phone: phone,
    pushName: data.pushName || '',
    message: message.trim(),
    instance: body.instance || '',
    timestamp: new Date().toISOString(),
    isAudio: false,
    config: {
      evolution_url: 'https://agentesn8n-evolution.cqc86v.easypanel.host',
      evolution_instance: 'Trade%20Brasil',
      dashboard_webhook_url: 'https://tradebrasil-dashboard.vercel.app/api/evolution-webhook',
      dashboard_webhook_secret: 'tradebrasil_evolution_secret_2026'
    }
  }
}];

const items = $input.all();
const init = $('Inicializar e Config').first().json;
const lead = (items.length > 0 && items[0].json && items[0].json.Id) ? items[0].json : null;

let historico = [];
try { if (lead && lead.resumo_conversa) historico = [{ role: 'assistant', content: lead.resumo_conversa }]; } catch(e) { historico = []; }

const dados_qual = {
  cultura_principal: lead ? (lead.cultura_principal || null) : null,
  volume_safra:      lead ? (lead.volume_safra || null) : null,
  volume_bois:       lead ? (lead.volume_bois || null) : null,
  estado:            lead ? (lead.estado || null) : null,
  momento_protecao:  lead ? (lead.momento_protecao || null) : null,
  horario_agendado:  lead ? (lead.horario_agendado || null) : null
};

const leadNome = lead ? (lead.nome || init.pushName || '') : (init.pushName || '');

return [{json: {
  phone: init.phone,
  pushName: init.pushName,
  lead_first_name: leadNome.split(' ')[0] || '',
  lead_nome_completo: leadNome,
  message: init.message,
  config: init.config,
  timestamp: init.timestamp,
  lead_exists: lead !== null,
  lead_id: lead ? lead.Id : null,
  historico: historico,
  dados_qualificacao: dados_qual,
  aguardando_especialista: lead ? (lead.aguardando_especialista === true || lead.aguardando_especialista === 1) : false,
  horario_agendado: lead ? lead.horario_agendado : null,
  resumo_conversa: lead ? lead.resumo_conversa : null
}}];

const ctx = $input.first().json;

const dadosColetados = Object.entries(ctx.dados_qualificacao || {})
  .filter(function(e) { return e[1] !== null && e[1] !== undefined && e[1] !== ''; })
  .map(function(e) { return e[0] + ': ' + e[1]; })
  .join(', ') || 'nenhum dado prévio registrado';

const conversaEmAndamento = Boolean(ctx.resumo_conversa || ctx.em_atendimento);

const contexto_sistema = '[CONTEXTO ATUAL DO PRODUTOR]\n'
  + 'Nome: ' + (ctx.lead_first_name || 'Produtor') + '\n'
  + 'Telefone: ' + ctx.phone + '\n'
  + 'Dados já conhecidos: ' + dadosColetados + '\n'
  + 'Status do diálogo: ' + (conversaEmAndamento 
      ? 'CONVERSA EM ANDAMENTO (NÃO repita saudações como "Oi [Nome]" ou "Olá", vá direto ao ponto com naturalidade)' 
      : 'PRIMEIRO CONTATO (saúde pelo nome com simpatia)') + '\n'
  + (ctx.horario_agendado ? ('Horário já agendado anteriormente: ' + ctx.horario_agendado + '\n') : '')
  + (ctx.resumo_conversa ? ('Resumo anterior: ' + ctx.resumo_conversa + '\n') : '');

return [{json: Object.assign({}, ctx, {
  contexto_sistema: contexto_sistema
})}];

const novoLead = $input.first().json;
const ctx = $('Preparar Contexto Lead').first().json;
return [{json: Object.assign({}, ctx, { lead_id: novoLead.Id, lead_exists: true })}];

const agentResp = $input.first().json;
const ctx = $('Preparar Input Agente').first().json;

const rawText = agentResp.output || '{}';

let parsed = null;

// 1. Tenta extrair qualquer bloco entre a primeira chave '{' e a última '}'
const jsonMatch = rawText.match(/\{[\s\S]*\}/);
if (jsonMatch) {
  try {
    parsed = JSON.parse(jsonMatch[0]);
  } catch(e) {
    parsed = null;
  }
}

// 2. Se falhou, tenta limpando tags markdown e espaços
if (!parsed) {
  const cleaned = rawText
    .replace(/^```json\s*/im, '')
    .replace(/^```\s*/im, '')
    .replace(/\s*```$/m, '')
    .trim();
  try {
    parsed = JSON.parse(cleaned);
  } catch(e) {
    parsed = null;
  }
}

// 3. Fallback defensivo: se não houver JSON válido, extrai apenas texto limpo humano
if (!parsed) {
  let safeText = rawText
    .replace(/```json[\s\S]*```/gi, '')
    .replace(/```[\s\S]*```/gi, '')
    .replace(/\{[\s\S]*\}/gi, '')
    .replace(/["'{}]/g, '')
    .trim();

  parsed = {
    mensagem_whatsapp: safeText || "Olá! Como posso te ajudar hoje?",
    novos_dados: {},
    aguardando_especialista: false,
    horario_agendado: null,
    resumo_conversa: null
  };
}

const mensagem = (parsed.mensagem_whatsapp || '').trim();
const novos_dados = parsed.novos_dados || {};
const aguardando_especialista = parsed.aguardando_especialista === true;
const horario_agendado = parsed.horario_agendado || ctx.horario_agendado || null;
const resumo_conversa = parsed.resumo_conversa || ctx.resumo_conversa || null;

const dados_qual = Object.assign({}, ctx.dados_qualificacao, novos_dados);
if (horario_agendado) dados_qual.horario_agendado = horario_agendado;

return [{json: Object.assign({}, ctx, {
  mensagem_whatsapp: mensagem,
  novos_dados: novos_dados,
  dados_qualificacao: dados_qual,
  aguardando_especialista: aguardando_especialista,
  horario_agendado: horario_agendado,
  resumo_conversa: resumo_conversa
})}];

const ctx = $input.first().json;
const dq = ctx.dados_qualificacao || {};

const patchBody = {
  Id: ctx.lead_id,
  em_atendimento: true,
  aguardando_especialista: ctx.aguardando_especialista || false,
  horario_agendado: ctx.horario_agendado || null,
  resumo_conversa: ctx.resumo_conversa || null
};

if (dq.cultura_principal) patchBody.cultura_principal = dq.cultura_principal;
if (dq.volume_safra)      patchBody.volume_safra = dq.volume_safra;
if (dq.volume_bois)       patchBody.volume_bois = dq.volume_bois;
if (dq.estado)            patchBody.estado = dq.estado;
if (dq.momento_protecao)  patchBody.momento_protecao = dq.momento_protecao;

return [{json: Object.assign({}, ctx, { patchBody: patchBody })}];

// 1. Nome e mensagem
const primeiroNome = $('Preparar Contexto Lead').first().json.lead_first_name || '';
let mensagem = $('Parsear Resposta e Agendamento').first().json.mensagem_whatsapp || '';
mensagem = mensagem
  .replace(/\[nome\]/gi, primeiroNome)
  .replace(/\{nome\}/gi, primeiroNome);

const LIMITE = 120;

// Divide sentenças sem quebrar números (R$ 240.000, 75hp, 4.000 RPM etc.)
// Só quebra em . ! ? quando o próximo caractere não-espaço for maiúsculo ou fim de string
function splitSentencas(texto) {
  var resultado = [];
  var atual = '';
  var i = 0;
  while (i < texto.length) {
    atual += texto[i];
    if ('.!?'.indexOf(texto[i]) !== -1) {
      var j = i + 1;
      // Avança pelos espaços à frente
      while (j < texto.length && texto[j] === ' ') { j++; }
      var proximoEhMaiusculo = j >= texto.length || /[A-ZÁÉÍÓÚÀÂÊÔÃÕÜÇ"'(]/.test(texto[j]);
      if (proximoEhMaiusculo) {
        resultado.push(atual.trim());
        atual = '';
        i = j - 1; // pula os espaços consumidos
      }
    }
    i++;
  }
  if (atual.trim()) resultado.push(atual.trim());
  return resultado.filter(function(p) { return p.length > 0; });
}

// Agrupa sentenças respeitando o limite de caracteres
function agrupar(sentencas) {
  var grupos = [];
  var atual = '';
  sentencas.forEach(function(s) {
    var candidato = atual ? atual + ' ' + s : s;
    if (candidato.length <= LIMITE) {
      atual = candidato;
    } else {
      if (atual) grupos.push(atual);
      atual = s; // mantém a sentença mesmo se ultrapassar o limite
    }
  });
  if (atual) grupos.push(atual);
  return grupos;
}

// FIX PRINCIPAL: divide por \n simples (não só \n\n)
// A Ana gera mensagens com \n entre frases, não \n\n
var linhas = mensagem
  .split('\n')
  .map(function(l) { return l.trim(); })
  .filter(function(l) { return l.length > 0; });

var partes = [];
linhas.forEach(function(linha) {
  if (linha.length <= LIMITE) {
    partes.push(linha);
  } else {
    agrupar(splitSentencas(linha)).forEach(function(g) { partes.push(g); });
  }
});

var resultado = partes.length > 0 ? partes : [mensagem];
return resultado.map(function(p) { return { json: { output: p } }; });

const texto = $json.output || '';
const delay = Math.min(5000, Math.max(1000, Math.floor(texto.length / 50) * 1000));
return [{ json: { ...$json, delay_ms: delay } }];

