const data = $input.first().json.body.data;

return [{
  json: {
    requestBody: {
      message: {
        key: data.key,
        message: data.message
      },
      convertToMp4: false
    }
  }
}];

const base64 = $input.first().json.base64;
const buffer = Buffer.from(base64, 'base64');

return [{
  json: {},
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'audio/ogg',
      fileName: 'audio.ogg',
      fileExtension: 'ogg'
    }
  }
}];

// Pega dados do webhook (pinData ainda está disponível via $('Receber Mensagem WhatsApp'))
const webhookData = $('Receber Mensagem WhatsApp').first().json;
const body = webhookData.body || {};
const data = body.data || {};
const key = data.key || {};
const remoteJid = key.remoteJid || '';
const phone = remoteJid.split('@')[0].replace(/[^0-9]/g, '');

// Pega o texto transcrito pelo Whisper
const transcribedText = $input.first().json.text || '';

return [{
  json: {
    phone: phone,
    pushName: data.pushName || '',
    message: transcribedText,
