const message = data.message?.conversation
  || data.message?.extendedTextMessage?.text
  || '';

// Escapa apóstrofos simples para proteger contra erros de sintaxe SQL no Postgres
const message_escaped = message.replace(/'/g, "''");

return [{ json: { ...($input.first().json), phone, message_raw: message, message_escaped } }];

